function stripeSignatureValid(string $body,string $header,string $secret,?int $now=null):bool{preg_match('/(?:^|,)\s*t=(\d+)/',$header,$timestamp);preg_match_all('/(?:^|,)\s*v1=([a-f0-9]{64})/',$header,$sigs);if(!$secret||!isset($timestamp[1])||abs(($now??time())-(int)$timestamp[1])>300)return false;$expected=hash_hmac('sha256',$timestamp[1].'.'.$body,$secret);foreach($sigs[1] as $sig)if(hash_equals($expected,$sig))return true;return false;}
function paymentConfig():array{return getRecord('secrets','stripe')??[];}
function stripeRequest(string $method,string $path,array $params=[],?array $config=null,string $idempotency=''):array{$c=$config??paymentConfig();if(empty($c['secret']))throw new RuntimeException('Stripe is not connected.');$url='https://api.stripe.com/v1/'.$path;if($method==='GET'&&$params)$url.='?'.http_build_query($params);$ch=curl_init($url);$headers=['Authorization: Bearer '.$c['secret'],'Stripe-Version: 2025-02-24.acacia'];if($idempotency)$headers[]='Idempotency-Key: '.$idempotency;curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>25,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_HTTPHEADER=>$headers,CURLOPT_CUSTOMREQUEST=>$method]);if($method!=='GET')curl_setopt($ch,CURLOPT_POSTFIELDS,http_build_query($params));$body=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);$data=json_decode((string)$body,true);if($code<200||$code>=300||!is_array($data))throw new RuntimeException('Stripe could not complete the request. Check the connection and key permissions.');return $data;}
function paymentReady():bool{$c=paymentConfig();return !empty($c['enabled'])&&!empty($c['secret'])&&!empty($c['webhook']);}
function safePaymentStatus():array{$c=paymentConfig();return ['connected'=>!empty($c['secret']),'enabled'=>paymentReady(),'mode'=>$c['mode']??'test','keySuffix'=>empty($c['secret'])?'':substr($c['secret'],-4),'webhookConfigured'=>!empty($c['webhook']),'endpoint'=>ORIGIN.'/api/stripe/webhook'];}
function bookingQuote(array $tour,array $input):array{$adults=filter_var($input['adults']??1,FILTER_VALIDATE_INT);$children=filter_var($input['children']??0,FILTER_VALIDATE_INT);$units=filter_var($input['units']??1,FILTER_VALIDATE_INT);if($adults===false||$children===false||$units===false||$adults<1||$children<0||$adults+$children>30||$units<1||$units>20)respond(['error'=>'Please select a valid number of guests and units.'],422);$base=price($tour);if($base<=0)respond(['error'=>'Please contact us for a current quote for this experience.'],422);$mode=$tour['pricingMode']??'per_person';$capacity=max(1,(int)($tour['capacity']??7));if($mode==='per_group'&&$adults+$children>$units*$capacity)respond(['error'=>'Please add enough vehicles for your group.'],422);if($mode==='per_hour'&&$adults+$children>$capacity)respond(['error'=>'The selected guest count exceeds the yacht capacity.'],422);$baseTotal=$mode==='per_person'?$base*($adults+$children):$base*$units;$extras=[];$total=$baseTotal;foreach($tour['addons']??[] as $a){$q=(int)($input['addons'][$a['id']]??0);if($q<0||$q>20)respond(['error'=>'Invalid extra quantity.'],422);if(!$q)continue;$line=($a['mode']??'per_unit')==='per_person'?($adults+$children)*(float)$a['price']:$q*(float)$a['price'];$total+=$line;$extras[]=['title'=>$a['title'],'quantity'=>$q,'amount'=>round($line,2)];}return ['adults'=>$adults,'children'=>$children,'units'=>$units,'baseTotal'=>round($baseTotal,2),'addons'=>$extras,'total'=>round($total,2),'amount'=> (int)round($total*100),'currency'=>'aed'];}
function completePayment(array $session):?array{$id=(string)($session['client_reference_id']??'');$pending=getRecord('checkout',$id);if(!$pending)return null;$config=paymentConfig();if(($session['payment_status']??'')!=='paid'||($session['status']??'')!=='complete')return null;if(($pending['sessionId']??'')!==($session['id']??'')||(int)$session['amount_total']!==$pending['amount']||strtolower($session['currency']??'')!=='aed'||(bool)($session['livemode']??false)!==($pending['mode']==='live'))throw new RuntimeException('Payment verification mismatch.');$db=database();$db->exec('BEGIN IMMEDIATE');try{$booking=getRecord('bookings',$id);if(!$booking){$booking=$pending;unset($booking['sessionToken']);$booking['paidAt']=gmdate('c');$booking['paymentStatus']='paid';$booking['status']='pending';$booking['paymentIntent']=$session['payment_intent']??'';putRecord('bookings',$id,$booking);$pending['paidAt']=$booking['paidAt'];putRecord('checkout',$id,$pending);}$db->exec('COMMIT');}catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}return $booking;}
function sendBookingReceipt(array $b):void{if(!empty($b['receiptAttemptedAt']))return;$body="Thank you for booking with Desert Sky Tourism.\n\nReference: {$b['reference']}\nExperience: {$b['tourTitle']}\nDate: {$b['date']}\nGuests: ".($b['adults']+$b['children'])."\nPaid: ".money($b['total'])."\n\nPayment received. Our team will confirm your tour arrangements separately.\n\nContact: ".settings()['email'].' | '.settings()['phone'];if(!empty($b['items'])){$body.="\n\nExperiences in your booking:\n";foreach($b['items'] as $item)$body.=$item['tourTitle']." — ".$item['date']." — ".money($item['total'])."\n";}if(!empty($b['customerId']))$body.="\nView your bookings: ".ORIGIN.'/account';$b['customerReceiptSent']=notifyMail($b['email'],'Payment received — '.$b['reference'],$body);$b['businessNotificationSent']=notifyMail(settings()['bookingEmail']??settings()['email'],'New paid booking — '.$b['reference'],$body."\n\nGuest: {$b['name']}\nEmail: {$b['email']}\nPhone: {$b['phone']}\nPickup: {$b['pickup']}\nNotes: {$b['notes']}");$b['receiptAttemptedAt']=gmdate('c');putRecord('bookings',$b['id'],$b);}
